    return (
        <>
            <Suspense fallback="Is loading...">
                <AsyncComponent title="Main app async component" />
            </Suspense>
            {/* <ActivityExample /> */}
        </>
    )
}

export default App

function AsyncComponent({ title }: { title: string }) {
