### Description

Extend the @let template declaration syntax to support optional type annotations, similar to TypeScript variable declarations:
```ts
@let myVar: MyType = myAny;
```
Eg.:
```ts
type MyType = { foo: boolean };

@Component({
  selector: 'app-root',
  template: `
    @let myVar: MyType = myAny;

    {{ myVar.foo }}
  `,
})
export class App {
  MyType!: MyType;
  myAny: any = { foo: true };
}
