  export function f(): Readable<Entity[]> {
    return readable([{ id: crypto.randomUUID() }], (_set, update) => {
      const timer = setInterval(() => {
        update((x) => [...x, { id: crypto.randomUUID() }]);
      }, 1000);

      return () => clearInterval(timer);
