```js
// app.js
const express = require('express');
const routes = require('./routes');
const app = express();

app.use('/', routes);

...

// routes.js
const express = require('express');
const router = express.Router();

router.get('/healthz', ...); // <-- fixed, no more errors
router.get('/version', ...); // <-- fixed, no more errors

...
